// Plan: clean up to 3 seed keywords. Each seed = 1 Amazon autocomplete search. No seeds = saved suggestions only (0 searches).
const MAX_SEEDS = 3;
const form = $('Ideas form').first().json;
const clean = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim().replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, '');
const all = String(form['Seed keywords'] || '').split(/[\n,;]+/).map(clean).filter(Boolean);
const tooShort = [...new Set(all.filter(w => w.replace(/[^a-z]/g, '').length < 3))];
const unique = [...new Set(all)].filter(w => !tooShort.includes(w));
const seeds = unique.slice(0, MAX_SEEDS);
const notes = [];
if (tooShort.length) notes.push(`Skipped (too short): ${tooShort.join(', ')}`);
if (unique.length > MAX_SEEDS) notes.push(`Only the first ${MAX_SEEDS} seeds were searched; left out: ${unique.slice(MAX_SEEDS).join(', ')}`);
if (!seeds.length) notes.push('No seeds: ideas come only from suggestions saved by earlier searches (0 searches)');
return [{ json: { batch_id: $now.toFormat('yyyy-MM-dd HH:mm:ss') + ' PKT', marketplace: form.Marketplace || 'amazon.com', seeds, any_seed: seeds.length > 0, notes } }];

// One item per seed keyword (1 SerpApi autocomplete search each)
const plan = $('Plan Ideas').first().json;
return plan.seeds.map(seed => ({ json: { seed, marketplace: plan.marketplace } }));

// Collect keyword ideas from 3 Amazon sources, clean them, and mark which ones were already screened.
//   1. Amazon autocomplete for each seed (new searches)
//   2. "Related searches" Amazon showed under keywords you already searched (saved in the Keywords tab, free)
//   3. "Shopping ideas" filters Amazon showed (saved, free), joined to their keyword: "with handles" -> "resistance bands with handles"
// No AI. Brand-name ideas are set aside using brands seen on your saved pages, not a guess.
const MAX_PASTE = 10;
const plan = $('Plan Ideas').first().json;
const mk = plan.marketplace;
const lc = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const key = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const stem = w => w.replace(/(es|s)$/, '');
const LINK = new Set(['for', 'with', 'without', 'and', 'the', 'of', 'in', 'on', 'to', 'a']);
const words = s => lc(s).replace(/[^a-z0-9' ]/g, ' ').split(' ').filter(Boolean);
// Same words in any order = same search ("travel neck pillow" = "neck pillow travel")
const sameKey = s => words(s).filter(w => !LINK.has(w)).map(stem).sort().join(' ');
const headOf = kw => stem(lc(kw).split(/ (?:for|with|without|in|on|to|of|and) /)[0].split(' ').pop() || '');

// ---- Saved keyword rows (latest per keyword) ----
const kwRows = $('Read Keywords').all().map(i => i.json).filter(r => r.status === 'ok' && r.marketplace === mk && r.keyword);
const latest = {};
for (const r of kwRows) if (!latest[r.keyword] || String(r.checked_at) > String(latest[r.keyword].checked_at)) latest[r.keyword] = r;
const screened = {};
for (const r of Object.values(latest)) {
  const k = sameKey(r.keyword);
  if (!screened[k] || String(r.checked_at) > String(screened[k].checked_at)) screened[k] = r;
}

// Pages saved by any tool (i3 keeps a page without a Keywords row when it reused or before Oct 17): searched, but no score here
const pageSaved = {};
for (const l of $('Read Listings').all().map(i => i.json)) {
  if (l.marketplace !== mk || !l.keyword) continue;
  const k = sameKey(l.keyword);
  if (!pageSaved[k] || String(l.checked_at) > pageSaved[k]) pageSaved[k] = String(l.checked_at);
}

// ---- Brands seen on your pages (established: 1000+ reviews), minus words that are product words ----
const productWords = new Set(Object.keys(latest).concat(plan.seeds).flatMap(words).map(w => stem(key(w))));
const NOT_BRANDS = new Set(['black', 'white', 'grey', 'gray', 'blue', 'pink', 'red', 'green', 'ultra', 'royal', 'luxury', 'soft', 'memory', 'comfort', 'best', 'travel', 'portable', 'adjustable', 'premium', 'kids', 'heavy', 'large', 'small', 'extra', 'super', 'new', 'original', 'professional']);
// A real brand leads its titles ("JOOLA Ben Johns…"); a generic word ("fabric", "hanging", "anti") mostly sits mid-title.
// So a title-guessed brand counts only if, across all saved titles containing it, it is the first word at least 60% of the time.
const listings = $('Read Listings').all().map(i => i.json).filter(l => l.marketplace === mk && l.title);
const firstWord = {}, anyWord = {};
for (const l of listings) {
  const ws = words(l.title).map(key).filter(Boolean);
  if (ws[0]) firstWord[ws[0]] = (firstWord[ws[0]] || 0) + 1;
  for (const w of new Set(ws)) anyWord[w] = (anyWord[w] || 0) + 1;
}
const brands = new Set();
for (const l of listings) {
  if (Number(l.reviews || 0) < 1000) continue;
  const b = key(l.brand_guess);
  if (b.length < 3 || productWords.has(stem(b)) || NOT_BRANDS.has(b)) continue;
  if ((firstWord[b] || 0) / (anyWord[b] || 1) >= 0.6) brands.add(b);
}
for (const p of $('Read Products').all().map(i => i.json)) {
  const b = key(p.real_brand);
  if (p.marketplace === mk && b.length >= 3 && b !== 'notfound' && !productWords.has(stem(b))) brands.add(b);
}
const brandIn = s => {
  const ws = words(s).map(key);
  const joined = ws.join('');
  return [...brands].find(b => ws.includes(b) || (b.length >= 6 && joined.includes(b))) || null;
};

// ---- Which saved keywords feed this run ----
const seedHeads = new Set(plan.seeds.map(headOf));
const parents = Object.values(latest).filter(r => !plan.seeds.length || plan.seeds.includes(r.keyword) || seedHeads.has(headOf(r.keyword)));

// ---- Gather ----
const ideas = {};
const add = (text, source, parent, order) => {
  const t = lc(text);
  if (!t || t.length < 3) return;
  const k = sameKey(t);
  if (!k) return;
  const it = (ideas[k] ??= { idea: t, variants: new Set(), sources: new Set(), parents: new Set(), first_order: 999 });
  if (t !== it.idea) it.variants.add(t);
  it.sources.add(source);
  it.parents.add(parent);
  it.first_order = Math.min(it.first_order, order);
};
let acFailed = [];
let acCount = 0;
try {
  if ($('Amazon Autocomplete (SerpApi)').isExecuted) {
    const res = $('Amazon Autocomplete (SerpApi)').all().map(i => i.json);
    plan.seeds.forEach((seed, i) => {
      const r = res[i] || {};
      if (r.error || !Array.isArray(r.suggestions)) { acFailed.push(seed); return; }
      r.suggestions.filter(s => !s.type || s.type === 'KEYWORD').forEach((s, j) => { acCount++; add(s.value, 'autocomplete', seed, j); });
    });
  }
} catch (e) { /* no seeds, autocomplete did not run */ }
for (const r of parents) {
  String(r.related_searches || '').split(' | ').forEach((s, j) => add(s, 'related searches', r.keyword, 20 + j));
  String(r.shopping_ideas || '').split(' | ').filter(Boolean).forEach((m, j) => {
    const mod = lc(m);
    if (!mod) return;
    const phrase = /^(with|for|without)\b/.test(mod) ? `${r.keyword} ${mod}` : `${mod} ${r.keyword}`;
    add(phrase, 'shopping filter', r.keyword, 40 + j);
  });
}

// ---- Judge each idea ----
const inputKeys = new Set([...plan.seeds, ...parents.map(p => p.keyword)].map(sameKey));
const heads = new Set([...seedHeads, ...parents.map(p => headOf(p.keyword))]);
const SRC_ORDER = ['autocomplete', 'related searches', 'shopping filter'];
let rows = Object.entries(ideas).filter(([k]) => !inputKeys.has(k)).map(([k, it]) => {
  const brand = brandIn(it.idea);
  const related = words(it.idea).map(stem).some(w => heads.has(w));
  const s = screened[k];
  return {
    idea: it.idea,
    group: brand ? 'brand name' : related ? 'same product' : 'nearby market',
    brand_found: brand || '',
    sources: SRC_ORDER.filter(x => it.sources.has(x)).join(' + '),
    source_count: it.sources.size,
    suggested_under: [...it.parents].join(' | '),
    mentions: it.parents.size,
    status: s ? 'screened' : pageSaved[k] ? 'page saved, not scored' : 'new',
    last_score: s ? s.opportunity_score : '',
    last_confidence: s ? s.confidence : '',
    last_checked: s ? s.checked_at : (pageSaved[k] || ''),
    same_as: [...it.variants].join(' | '),
    _order: it.first_order,
  };
});
// Order: same product first, then nearby markets, brands last; within a group: more sources, more mentions, Amazon's own order
const G = { 'same product': 0, 'nearby market': 1, 'brand name': 2 };
rows.sort((a, b) => (G[a.group] - G[b.group]) || (b.source_count - a.source_count) || (b.mentions - a.mentions) || (a._order - b._order) || a.idea.localeCompare(b.idea));
const total = rows.length;
const groups = { same_product: rows.filter(r => r.group === 'same product').length, nearby_market: rows.filter(r => r.group === 'nearby market').length, brand_name: rows.filter(r => r.group === 'brand name').length };
// Listed: up to 60 same-product, 25 nearby-market and 15 brand-name ideas, so every group stays visible
const CAP = { 'same product': 60, 'nearby market': 25, 'brand name': 15 };
const seen = {};
rows = rows.filter(r => (seen[r.group] = (seen[r.group] || 0) + 1) <= CAP[r.group]).map(({ _order, ...r }, i) => ({ rank: i + 1, ...r }));

const paste = rows.filter(r => r.group === 'same product' && r.status === 'new').slice(0, MAX_PASTE).map(r => r.idea);
const notes = [...plan.notes];
if (acFailed.length) notes.push(`Autocomplete failed for: ${acFailed.join(', ')}`);
if (plan.seeds.length && !parents.length) notes.push('None of your saved keywords match these seeds yet, so saved suggestions add nothing; run them through i1 to collect more');
if (total > rows.length) notes.push(`${total} ideas found; the top ${rows.length} are listed (up to 60 same-product, 25 nearby-market, 15 brand-name)`);
return [{
  json: {
    rows,
    total,
    groups,
    paste,
    parents_used: parents.map(p => p.keyword),
    autocomplete_suggestions: acCount,
    searches_used: plan.seeds.length,
    notes,
  },
}];

// One Keyword Ideas row per idea, keyed by run
const plan = $('Plan Ideas').first().json;
const run_id = `i5|${plan.marketplace}|${plan.batch_id}`;
return $('Collect Ideas').first().json.rows.map(r => ({ json: { row_id: `${run_id}|${r.rank}`, run_id, checked_at: plan.batch_id, marketplace: plan.marketplace, seeds: plan.seeds.join(' | '), ...r } }));

// One Idea Runs row (cost, counts, the paste-ready list for i1) + the text shown on the form
const plan = $('Plan Ideas').first().json;
const c = $('Collect Ideas').first().json;
const run_id = `i5|${plan.marketplace}|${plan.batch_id}`;
const row = {
  row_id: run_id, run_id, checked_at: plan.batch_id, tool: 'i5', marketplace: plan.marketplace,
  seeds: plan.seeds.join(' | '), searches_used: c.searches_used, autocomplete_suggestions: c.autocomplete_suggestions,
  saved_keywords_used: c.parents_used.join(' | '), ideas_found: c.total, listed: c.rows.length,
  same_product: c.groups.same_product, nearby_market: c.groups.nearby_market, brand_name: c.groups.brand_name,
  new_ideas: c.rows.filter(r => r.status === 'new').length, already_screened: c.rows.filter(r => r.status === 'screened').length,
  paste_into_i1: c.paste.join('\n'), notes: c.notes.join(' | '),
  cannot_tell: 'search volume of any idea | whether an idea is a real market until i1 screens it',
};
const screenedTop = c.rows.filter(r => r.status === 'screened').slice(0, 3).map(r => `${r.idea} (${r.last_score}/100)`);
const summary_text = [
  `${c.total} ideas (${row.same_product} same product, ${row.nearby_market} nearby markets, ${row.brand_name} brand names) on ${plan.marketplace}. Searches used: ${c.searches_used}.`,
  c.paste.length ? `New, ready to paste into i1 (${c.paste.length}):\n${c.paste.join('\n')}` : 'No new same-product ideas: everything found was already screened.',
  ...(screenedTop.length ? [`Already screened: ${screenedTop.join(', ')}`] : []),
  ...(c.rows.some(r => r.group === 'nearby market') ? [`Nearby markets: ${c.rows.filter(r => r.group === 'nearby market').slice(0, 5).map(r => r.idea).join(', ')}`] : []),
  ...(c.notes.length ? [`Notes: ${c.notes.join(' · ')}`] : []),
].join('\n');
return [{ json: { ...row, summary_text } }];

// The Idea Runs row without the form-only text
const { summary_text, ...row } = $('Run Summary').first().json;
return [{ json: row }];

// ---- Result page: shared design (Amazon Toolkit). Presentation only: every value is copied from earlier nodes. ----
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const CURS = { 'amazon.com': '$', 'amazon.co.uk': '£', 'amazon.ca': 'C$' };
const num = v => (v === '' || v === null || v === undefined || Number.isNaN(Number(v)) ? null : Number(v));
const int = v => (num(v) === null ? '–' : Math.round(num(v)).toLocaleString('en-US'));
const money = (v, cur) => (num(v) === null ? '–' : `${cur}${num(v).toFixed(2)}`);
const big = (v, cur = '') => { const n = num(v); if (n === null) return '–'; if (n >= 1e6) return `${cur}${(n / 1e6).toFixed(2)}M`; if (n >= 1e4) return `${cur}${Math.round(n / 1e3)}K`; return `${cur}${int(n)}`; };
const rating = v => (num(v) === null ? '–' : num(v).toFixed(1));
const spots = t => esc(String(t ?? '').split(' | ').join(' · '));
const split = t => String(t ?? '').split(' | ').map(s => s.trim()).filter(Boolean);
const LEVEL = { high: 'yes', medium: 'mid', low: 'no' };
const pill = (text, kind) => `<span class="pill ${kind || ''}">${esc(text)}</span>`;
const levelPill = t => pill(t, LEVEL[String(t || '').toLowerCase()] || 'muted');
const tiles = list => `<div class="tiles">${list.map(([v, l]) => `<div class="tile"><div class="tv">${v}</div><div class="tl">${esc(l)}</div></div>`).join('')}</div>`;
const section = (title, body) => (body ? `<section><h2>${esc(title)}</h2>${body}</section>` : '');
const table = (head, rows, right = []) => `<div class="tw"><table><thead><tr>${head.map((h, i) => `<th${right.includes(i) ? ' class="r"' : ''}>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map((c, i) => `<td${right.includes(i) ? ' class="r"' : ''}>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const notesList = list => (list.length ? `<ul class="notes">${list.map(n => `<li>${esc(n)}</li>`).join('')}</ul>` : '');
const chips = list => (list.length ? `<div class="chips">${list.map(c => `<span class="chip">${esc(c)}</span>`).join('')}</div>` : '');

function page({ code, tool, colour, tint, title, meta, verdict, body, saved, cannotTell }) {
