// i5 Next Keywords: result page
const r = $('Run Summary').first().json;
const c = $('Collect Ideas').first().json;
const ideas = c.rows || [];
const same = ideas.filter(x => x.group === 'same product').slice(0, 15);
const st = s => `<span class="pill ${s === 'new' ? 'yes' : s === 'screened' ? 'muted' : 'mid'}">${esc(s)}</span>`;
const paste = String(r.paste_into_i1 || '');
const html = page({
  code: 'i5', tool: 'Next Keywords', colour: '#214235', tint: '#edf3ef',
  title: r.seeds ? split(r.seeds).join(' · ') : 'Ideas from saved searches', meta: [r.marketplace, r.checked_at, `${r.searches_used} searches`],
  verdict: `<div class="big">${int(r.ideas_found)} ideas · ${int(r.new_ideas)} new</div><p>${esc(r.same_product)} same product · ${esc(r.nearby_market)} nearby markets · ${esc(r.brand_name)} brand names set aside</p>`,
  body: [
    section('Ready to paste into i1', paste ? `<textarea class="paste" id="paste" readonly>${esc(paste)}</textarea><button class="btn" onclick="var t=document.getElementById('paste');t.select();(navigator.clipboard?navigator.clipboard.writeText(t.value):Promise.reject()).then(function(){event.target.textContent='Copied'}).catch(function(){document.execCommand('copy');event.target.textContent='Copied'})">Copy list</button>` : '<p>No new same-product ideas: everything found was already screened.</p>'),
    section('Same product', table(['Idea', 'Found in', 'Status'], same.map(x => [`<b>${esc(x.idea)}</b>${x.same_as ? `<div class="sub">also: ${esc(String(x.same_as).split(' | ').join(', '))}</div>` : ''}`, `<span class="sub">${esc(x.sources)}</span>`, st(x.status) + (x.last_score !== '' && x.last_score !== undefined && x.last_score !== null ? ` <span class="sub">${esc(x.last_score)}/100</span>` : '')]))),
    section('Nearby markets', chips(ideas.filter(x => x.group === 'nearby market').slice(0, 12).map(x => x.idea))),
    section('Brand names set aside', chips(ideas.filter(x => x.group === 'brand name').slice(0, 12).map(x => x.idea))),
    section('Notes', notesList(split(r.notes))),
  ].join(''),
  saved: 'Keyword Ideas, Idea Runs',
  cannotTell: split(r.cannot_tell),
});
return [{ json: { html } }];
